(()=>{
 const $=id=>document.getElementById(id),esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');let current=null,token=0;
 const names={closed_edges:'Enclosed edges · medium',closed_edges_fine:'Enclosed edges · fine',closed_edges_coarse:'Enclosed edges · coarse',seeded_gradient_flood:'Seeded gradient flood'};
 function clean(out){return JSON.parse(JSON.stringify(out,(key,value)=>['labels','edges','boundary','masks','mask'].includes(key)?undefined:value));}
 function state(o){return o.value==null?'? Unresolved':'✓ '+String(o.value).replaceAll('_',' ');}
 function card(title,body){return `<article class="character"><h3>${title}</h3>${body}</article>`;}
 function measured(o){return `<div class="state">${esc(state(o))}</div><p>${esc(o.reason)}</p>${o.evidence.length?`<small>Evidence: ${o.evidence.map(e=>e.region?'region '+e.region:e.view==='centreMaskPreview'?'centre region':'outer-ray region').join(', ')}</small>`:''}`;}
 function render(){const {out,canvas}=current,o=out.observations,m=out.morphology;if(typeof LeafView!=='undefined'){LeafView.render(current);$('leafOrgan').textContent=out.leaf?.selectedId?'◇ Nearby leaf region · association unverified':'? Leaf region unresolved';}
  $('flowerOrgan').textContent=out.quality.usable?'✓ Flower-region measurement available':'? Flower region unresolved';
  const colours=['pink','red','yellow','blue','pale'].filter(k=>out.features[k]>=.15);const colourNode=card('Region colour',`<div class="state">${out.quality.usable&&colours.length?'✓ '+colours.join(' / '):'? Unresolved'}</div><p>Colours measured inside the proposed flower region. Pale pixels are not a verified white petal.</p><small>Evidence: cropped region pixels</small>`);
  $('characterNodes').innerHTML=colourNode+card('Petal-region shape',measured(o.petalShape)+'<p class="extra">— Individual tip not measured</p>')+
   card('Visible count',measured(o.visibleCount)+`<p class="extra" id="exploratoryCount">◇ Choose a region proposal</p><small>Regions are not verified petals. No hidden petals inferred.</small>`)+
   card('Petal arrangement','<div class="state">— Not measured</div><p>Whorls and overlapping layers require traced petal boundaries.</p>')+
   card('Flower centre',measured(o.centre)+'<p class="extra">— Column / stamen anatomy not measured</p>')+
   card('Leaf shape & attachment',typeof LeafView==='undefined'?'Not measured':LeafView.summary(out.leaf));
  const top=out.candidates[0],tied=out.candidates.filter(r=>Math.abs(r.score-top.score)<.001);
  $('decision').textContent=!out.quality.usable?'No reliable flower region':tied.length>1?`Ambiguous · ${tied.length} tied candidates`:'Candidate for investigation · '+top.name;
  $('candidates').innerHTML=out.candidates.map(r=>{const matches=r.evidence.filter(e=>!e.contradiction&&!e.unknown),conflicts=r.evidence.filter(e=>e.contradiction);const list=a=>a.slice(0,4).map(e=>`<li>${esc(e.feature.replaceAll('_',' '))}: ${esc(typeof e.value==='number'?e.value.toFixed(2):e.value)}</li>`).join('');return `<article class="candidate"><h3>${esc(r.name)}</h3><small>${esc(r.latin)} · score ${r.score.toFixed(3)}</small><p>Leaf reference: ${esc(r.leaf_evidence?.reference_shapes?.join(', ')||'unavailable')} · leaf coverage: ${Math.round((r.leaf_evidence?.coverage||0)*100)}%</p><p>Flower score: ${r.flower_score?.toFixed(3)??r.score.toFixed(3)} · leaf compatibility: ${r.leaf_evidence?.score==null?'unresolved':r.leaf_evidence.score.toFixed(2)} · adjustment: ${r.leaf_adjustment?.toFixed(3)||'0.000'}</p><p>Measured profile coverage: ${Math.round(r.coverage*100)}%</p><p>Missing measurements: ${esc(r.missing_features.join(', ').replaceAll('_',' ')||'None in this profile')}</p><p>Supporting existing measurements</p><ul>${list(matches)||'<li>None</li>'}</ul><p>Conflicting measurements</p><ul>${list(conflicts)||'<li>None measured</li>'}</ul><p class="muted">Unassessed: verified petal count, layers, central column and leaf anatomy.</p></article>`;}).join('');
  const ctx=$('crop').getContext('2d');$('crop').width=canvas.width;$('crop').height=canvas.height;ctx.drawImage(canvas,0,0);
  const e=$('edges');e.width=canvas.width;e.height=canvas.height;const ex=e.getContext('2d'),ei=ex.createImageData(e.width,e.height);for(let p=0;p<e.width*e.height;p++){const v=Math.min(255,18+(m?.edges[p]||0)*1800);ei.data.set([v,v,v,255],p*4);}ex.putImageData(ei,0,0);
  $('methods').innerHTML=(m?.methods||[]).map((r,i)=>`<button type="button" data-method="${i}" aria-pressed="false">${names[r.name]} (${r.count})</button>`).join('');
  for(const button of $('methods').querySelectorAll('button'))button.addEventListener('click',()=>showMethod(Number(button.dataset.method)));
  $('raw').textContent=JSON.stringify(clean(out),null,2);$('export').disabled=false;showMethod(0);
 }
 function showMethod(index){const {out,canvas}=current,m=out.morphology?.methods[index],c=$('regions');c.width=canvas.width;c.height=canvas.height;const ctx=c.getContext('2d');ctx.drawImage(canvas,0,0);
  if(m){const overlay=document.createElement('canvas');overlay.width=c.width;overlay.height=c.height;const ox=overlay.getContext('2d'),im=ox.createImageData(c.width,c.height);for(let p=0;p<m.labels.length;p++){const id=m.labels[p];if(id){const v=id%2?255:0;im.data.set([v,v,v,90],p*4);}}ox.putImageData(im,0,0);ctx.drawImage(overlay,0,0);ctx.font='bold 12px Arial';ctx.textAlign='center';ctx.textBaseline='middle';for(const r of m.regions){ctx.fillStyle='white';ctx.strokeStyle='black';ctx.beginPath();ctx.arc(r.x,r.y,9,0,2*Math.PI);ctx.fill();ctx.stroke();ctx.fillStyle='black';ctx.fillText(r.id,r.x,r.y);}
   const range=m.countRange?` · threshold variants ${m.countRange[0]}–${m.countRange[1]}`:'';$('proposalNote').textContent=`${m.count} exploratory regions${range}. These do not enter the identification score.`;$('exploratoryCount').textContent='◇ Proposal: '+m.count+' regions';$('regionCaption').textContent='04 '+names[m.name]+' · exploratory';
  }else{$('proposalNote').textContent=out.morphology?.reason||'No region proposal';$('exploratoryCount').textContent='◇ No region proposal';$('regionCaption').textContent='04 Region proposals unavailable';}
  for(const b of $('methods').querySelectorAll('button'))b.setAttribute('aria-pressed',String(Number(b.dataset.method)===index));
 }
 $('photo').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const run=++token;current=null;$('leafNote').textContent='Measuring leaves…';$('original').hidden=true;$('original').removeAttribute('src');$('flowerOrgan').textContent='Flower region · measuring';$('export').disabled=true;$('status').textContent='Measuring morphology…';$('characterNodes').innerHTML='';$('candidates').innerHTML='';$('methods').innerHTML='';$('raw').textContent='{}';$('decision').textContent='Measuring…';$('proposalNote').textContent='';for(const id of ['crop','edges','regions','leafCandidates','leafBlade','leafOutline']){const c=$(id);c.getContext('2d').clearRect(0,0,c.width,c.height);}const url=URL.createObjectURL(file),img=new Image();
  try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Could not decode this image'));img.src=url;});if(run!==token)return;$('original').src=url;await $('original').decode();if(run!==token)return;$('original').hidden=false;await new Promise(requestAnimationFrame);const result=FlowerImage.analyze(img,ENGINE_PROFILES);if(run!==token)return;current=result;render();$('status').textContent='Analysis complete · proposals remain exploratory. The diagram checks measurements, not expected species traits.';}
  catch(error){if(run===token)$('status').textContent=error.message;}
  finally{URL.revokeObjectURL(url);}
 });
 $('export').addEventListener('click',()=>{if(!current)return;const url=URL.createObjectURL(new Blob([JSON.stringify(clean(current.out),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='flower-characters.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 $('characterNodes').innerHTML=['Region colour','Petal-region shape','Visible count','Petal arrangement','Flower centre','Leaf shape & attachment'].map(title=>card(title,'<p>Awaiting image</p>')).join('');
})();
